from ortools.sat.python import cp_model
import itertools
import json

def main():
    model = cp_model.CpModel()

    container_length = 5
    container_width = 3
    container_height = 8

    product_types = [1, 2]

    product_dims = {
        1: (1, 3, 4),
        2: (4, 2, 5)
    }

    available_count = {1: 4, 2: 10}

    max_units = {t: available_count[t] for t in product_types}

    rotations = list(range(6))

    def get_rotation_dims(l, w, h, rot_idx):
        permutations = [
            (l, w, h), (l, h, w),
            (w, l, h), (w, h, l),
            (h, l, w), (h, w, l)
        ]
        return permutations[rot_idx]

    is_active = {}
    for t in product_types:
        for i in range(max_units[t]):
            is_active[(i, t)] = model.NewBoolVar(f"is_active_{i}_{t}")

    placed_count = {}
    for t in product_types:
        placed_count[t] = model.NewIntVar(0, max_units[t], f"placed_count_{t}")

    x = {}
    y = {}
    z = {}
    orientation = {}
    oriented_length = {}
    oriented_width = {}
    oriented_height = {}

    for t in product_types:
        l0, w0, h0 = product_dims[t]
        max_dim = max(l0, w0, h0)
        for i in range(max_units[t]):
            x[(i, t)] = model.NewIntVar(0, container_length, f"x_{i}_{t}")
            y[(i, t)] = model.NewIntVar(0, container_width, f"y_{i}_{t}")
            z[(i, t)] = model.NewIntVar(0, container_height, f"z_{i}_{t}")

            orientation[(i, t)] = model.NewIntVar(0, 5, f"orientation_{i}_{t}")

            oriented_length[(i, t)] = model.NewIntVar(0, max_dim, f"oriented_length_{i}_{t}")
            oriented_width[(i, t)] = model.NewIntVar(0, max_dim, f"oriented_width_{i}_{t}")
            oriented_height[(i, t)] = model.NewIntVar(0, max_dim, f"oriented_height_{i}_{t}")

    for t in product_types:
        model.Add(placed_count[t] == sum(is_active[(i, t)] for i in range(max_units[t])))

    for t in product_types:
        model.Add(placed_count[t] <= available_count[t])

    for t in product_types:
        l0, w0, h0 = product_dims[t]
        for i in range(max_units[t]):
            rot_indicator = {}
            for rot in rotations:
                rot_indicator[(i, t, rot)] = model.NewBoolVar(f"rot_indicator_{i}_{t}_{rot}")

            model.Add(sum(rot_indicator[(i, t, rot)] for rot in rotations) == is_active[(i, t)])

            for rot in rotations:
                model.Add(orientation[(i, t)] == rot).OnlyEnforceIf(rot_indicator[(i, t, rot)])

                rot_l, rot_w, rot_h = get_rotation_dims(l0, w0, h0, rot)

                model.Add(oriented_length[(i, t)] == rot_l).OnlyEnforceIf(rot_indicator[(i, t, rot)])
                model.Add(oriented_width[(i, t)] == rot_w).OnlyEnforceIf(rot_indicator[(i, t, rot)])
                model.Add(oriented_height[(i, t)] == rot_h).OnlyEnforceIf(rot_indicator[(i, t, rot)])

    M = 1000
    for t in product_types:
        for i in range(max_units[t]):
            model.Add(x[(i, t)] + oriented_length[(i, t)] <= container_length + M * (1 - is_active[(i, t)]))

            model.Add(y[(i, t)] + oriented_width[(i, t)] <= container_width + M * (1 - is_active[(i, t)]))

            model.Add(z[(i, t)] + oriented_height[(i, t)] <= container_height + M * (1 - is_active[(i, t)]))

    all_products = []
    for t in product_types:
        for i in range(max_units[t]):
            all_products.append((i, t))

    for idx1, (i1, t1) in enumerate(all_products):
        for idx2, (i2, t2) in enumerate(all_products):
            if idx1 >= idx2:
                continue

            left_of = model.NewBoolVar(f"left_of_{i1}_{t1}_{i2}_{t2}")
            right_of = model.NewBoolVar(f"right_of_{i1}_{t1}_{i2}_{t2}")
            behind = model.NewBoolVar(f"behind_{i1}_{t1}_{i2}_{t2}")
            front_of = model.NewBoolVar(f"front_of_{i1}_{t1}_{i2}_{t2}")
            below = model.NewBoolVar(f"below_{i1}_{t1}_{i2}_{t2}")
            above = model.NewBoolVar(f"above_{i1}_{t1}_{i2}_{t2}")

            model.Add(x[(i1, t1)] + oriented_length[(i1, t1)] <= x[(i2, t2)]).OnlyEnforceIf(left_of)

            model.Add(x[(i2, t2)] + oriented_length[(i2, t2)] <= x[(i1, t1)]).OnlyEnforceIf(right_of)

            model.Add(y[(i1, t1)] + oriented_width[(i1, t1)] <= y[(i2, t2)]).OnlyEnforceIf(behind)

            model.Add(y[(i2, t2)] + oriented_width[(i2, t2)] <= y[(i1, t1)]).OnlyEnforceIf(front_of)

            model.Add(z[(i1, t1)] + oriented_height[(i1, t1)] <= z[(i2, t2)]).OnlyEnforceIf(below)

            model.Add(z[(i2, t2)] + oriented_height[(i2, t2)] <= z[(i1, t1)]).OnlyEnforceIf(above)

            model.AddBoolOr([left_of, right_of, behind, front_of, below, above]).OnlyEnforceIf(
                [is_active[(i1, t1)], is_active[(i2, t2)]])

    for t in product_types:
        for i in range(max_units[t]):
            model.Add(x[(i, t)] == 0).OnlyEnforceIf(is_active[(i, t)].Not())
            model.Add(y[(i, t)] == 0).OnlyEnforceIf(is_active[(i, t)].Not())
            model.Add(z[(i, t)] == 0).OnlyEnforceIf(is_active[(i, t)].Not())

    total_container_volume = container_length * container_width * container_height

    product_volume = {}
    total_packed_volume = model.NewIntVar(0, total_container_volume, "total_packed_volume")

    volume_terms = []
    for t in product_types:
        for i in range(max_units[t]):
            vol_var = model.NewIntVar(0, total_container_volume, f"volume_{i}_{t}")

            length_width = model.NewIntVar(0, total_container_volume, f"length_width_{i}_{t}")
            model.AddMultiplicationEquality(length_width, [oriented_length[(i, t)], oriented_width[(i, t)]])

            length_width_height = model.NewIntVar(0, total_container_volume, f"length_width_height_{i}_{t}")
            model.AddMultiplicationEquality(length_width_height, [length_width, oriented_height[(i, t)]])

            model.Add(vol_var == length_width_height).OnlyEnforceIf(is_active[(i, t)])
            model.Add(vol_var == 0).OnlyEnforceIf(is_active[(i, t)].Not())

            volume_terms.append(vol_var)

    model.Add(total_packed_volume == sum(volume_terms))

    model.Maximize(total_packed_volume)

    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = 30.0
    solver.parameters.num_search_workers = 8

    status = solver.Solve(model)

    if status in (cp_model.OPTIMAL, cp_model.FEASIBLE):
        total_container_volume_val = container_length * container_width * container_height
        obj_value = solver.Value(total_packed_volume)
        volume_utilization = obj_value / total_container_volume_val

        placements = []
        for t in product_types:
            for i in range(max_units[t]):
                if solver.Value(is_active[(i, t)]) == 1:
                    x_val = solver.Value(x[(i, t)])
                    y_val = solver.Value(y[(i, t)])
                    z_val = solver.Value(z[(i, t)])
                    length_val = solver.Value(oriented_length[(i, t)])
                    width_val = solver.Value(oriented_width[(i, t)])
                    height_val = solver.Value(oriented_height[(i, t)])

                    placement_entry = [
                        t,
                        [x_val, y_val, z_val],
                        [length_val, width_val, height_val]
                    ]
                    placements.append(placement_entry)

        result = {
            "placements": placements,
            "volume_utilization": volume_utilization
        }
    else:
        result = {
            "placements": [],
            "volume_utilization": 0.0
        }

    print(json.dumps(result))

if __name__ == "__main__":
    main()
